{
  "packet_id": "H6-T04-2",
  "claim_id": "C026",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C026.main",
    "value": "A documented wait for a stated roster date counts as an explained interval.",
    "scope": "Conditional on documentation of the wait and a stated date; it does not guarantee later publication.",
    "provenance": {
      "refs": [
        {
          "source_id": "P014",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span supplies the documentary condition and the bounded interpretation of the interval."
    }
  },
  "signal_basis": {
    "component_id": "C026.signal_basis",
    "value": "Customer follow-up documents that an account is waiting until a stated roster date, providing a recorded explanation for the interval.",
    "scope": "Assumed observed as instructed. The explanation requires affirmative documentation; silence alone does not establish postponement, and intended roster dates may change.",
    "provenance": {
      "refs": [
        {
          "source_id": "P004",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P024",
          "role": "SUPPORT"
        },
        {
          "source_id": "P016",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans establish how intended timing is documented, what qualifies as an explained interval, and the limits of that timing information. P016 identifies the observations as proposed."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C026.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required for this bounded documentary interpretation."
    }
  },
  "rationale": "Documentation of a wait tied to a stated roster date supplies an explanation for the interval in the recorded history. This licenses the specific claim without establishing that the explanation is truthful or that publication will occur.",
  "uncertainty": "The accuracy of the reported reason and eventual publication remain unresolved; neither is asserted by this claim.",
  "anomalies": []
}
